fun stx expectedType? =>
  have __discr := stx;
  if __discr.isOfKind `letImplDetailStx = true then
    have __discr_1 := __discr.getArg 0;
    have __discr_2 := __discr.getArg 1;
    have __discr_3 := __discr.getArg 2;
    have __discr_4 := __discr.getArg 3;
    have __discr_5 := __discr.getArg 4;
    have __discr := __discr.getArg 5;
    have body := { raw := __discr };
    have valStx := { raw := __discr_4 };
    have id := { raw := __discr_2 };
    do
    let val ← Lean.Elab.Term.elabTerm valStx.raw none
    let type ← liftM (Lean.Meta.inferType val)
    have cls : Lean.Name := `Elab.let.decl
    let __do_lift ← Lean.isTracingEnabledFor cls
    have __do_jp : Unit → Lean.Elab.TermElabM Lean.Expr := fun __r =>
      Lean.Meta.withLetDecl id.getId type val fun x => do
        Lean.Elab.Term.addLocalVarInfo id.raw x
        let lctx ← Lean.getLCtx
        have lctx : Lean.LocalContext :=
          lctx.modifyLocalDecl x.fvarId! fun decl => decl.setKind Lean.LocalDeclKind.implDetail
        let __do_lift ← liftM Lean.Meta.getLocalInstances
        Lean.Meta.withLCtx lctx __do_lift do
            let body ← Lean.Elab.Term.elabTermEnsuringType body.raw expectedType?
            let body ← Lean.instantiateMVars body
            liftM (Lean.Meta.mkLetFVars #[x] body false)
    if __do_lift = true then do
        let __r ←
          Lean.addTrace cls
              (Lean.toMessageData id.getId ++ Lean.toMessageData " : " ++ Lean.toMessageData type ++
                  Lean.toMessageData " := " ++
                Lean.toMessageData val)
        __do_jp __r
      else __do_jp ()
  else
    have __discr := stx;
    Lean.Elab.throwUnsupportedSyntax

